          :direction="direction"
          :busy="busy"
          :quiet="quiet"
          :landing="dropping"
          :notes="notes"
          :prompts="promptEdits"
          :notes-failed="notesFailed"
          :artifacts="artifacts"
          :stage="stageNow"
          :reading="readingNow"
          :loading="settling"
          :setup="setupNeeded"
          @settings="toSettings"
          @prompt-save="savePromptFor($event)"
          @prompt-reset="resetPromptFor($event)"
          @go="go"
          @jump="jumpTo"
          @act="act"
          @ask="ask"
          @pin="pin"
          @resolve="resolveNote"
